import{_ as i,o as l,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-02-14","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-02-14","date":"2024-02-14T00:00:00.000Z","updated":"2024-02-15T00:00:00.000Z","tags":["Ceph","RGW","IAM策略","分布式存储","代码审查"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-02-14.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-02-14.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-02-14.md"};function r(n,a,h,s,d,c){return l(),e("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph存储系统iam策略限制讨论及项目进展更新" tabindex="-1">会议主题：Ceph存储系统IAM策略限制讨论及项目进展更新 <a class="header-anchor" href="#会议主题-ceph存储系统iam策略限制讨论及项目进展更新" aria-label="Permalink to &quot;会议主题：Ceph存储系统IAM策略限制讨论及项目进展更新&quot;">​</a></h4><h4 id="与会人员-ozan、nicholas-产品团队-、matt等" tabindex="-1">与会人员：Ozan、Nicholas（产品团队）、Matt等 <a class="header-anchor" href="#与会人员-ozan、nicholas-产品团队-、matt等" aria-label="Permalink to &quot;与会人员：Ozan、Nicholas（产品团队）、Matt等&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-视频会议" tabindex="-1">会议地点：视频会议 <a class="header-anchor" href="#会议地点-视频会议" aria-label="Permalink to &quot;会议地点：视频会议&quot;">​</a></h4><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容： <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容：&quot;">​</a></h4><ol><li><p><strong>IAM策略限制讨论</strong></p><ul><li>Ozan和Nicholas（产品团队）讨论了将IAM和STS产品化的过程中遇到的IAM策略限制问题。</li><li>讨论了AWS对IAM策略的限制，如策略长度、角色关联的策略数量等。</li><li>目前Ceph（SEF）在这些方面没有明确的限制，但考虑未来可能引入限制，可能会导致兼容性问题。</li><li>建议对所有IAM相关元数据设置限制，以避免未来出现问题。</li><li>Ozan将创建一个跟踪器来监控和处理这个问题。</li></ul></li><li><p><strong>账户实现进展</strong></p><ul><li>账户功能的实现已基本完成，但尚未进行代码审查和测试。</li><li>计划进行代码审查和测试，并可能进行代码走查。</li></ul></li><li><p><strong>对象完整性功能更新</strong></p><ul><li>Matt正在开发对象完整性功能，重点关注多部分上传（multipart uploads）的API覆盖。</li><li>决定继续完善该功能，特别是解决多部分上传的相关问题。</li></ul></li><li><p><strong>Squid版本代码冻结通知</strong></p><ul><li>代码冻结将于本周五进行，之后所有新功能和修复需要通过主干合并并进行回溯。</li><li>包括校验和功能和主题元数据迁移等关键功能需要在冻结前完成。</li></ul></li><li><p><strong>多站点测试和复制头更新</strong></p><ul><li>正在进行Squid版本的负载测试，并引入新的复制头（X-Replicated-At）以满足特定需求。</li><li>该功能将作为Squid版本的一部分，并可能在未来版本中进一步讨论和完善。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>创建一个跟踪器来监控和处理IAM策略限制问题。</li><li>进行账户功能的代码审查和测试，并可能进行代码走查。</li><li>继续完善对象完整性功能，特别是多部分上传的API覆盖。</li><li>确保关键功能在Squid版本代码冻结前完成。</li><li>引入新的复制头（X-Replicated-At）并计划在Squid版本中使用。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Ozan将创建一个跟踪器来监控IAM策略限制问题。</li><li>进行账户功能的代码审查和测试，并准备代码走查。</li><li>Matt将继续与团队合作，完善对象完整性功能。</li><li>确保所有关键功能在Squid版本代码冻结前完成。</li><li>进一步讨论和完善多站点测试和复制头功能。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><p>感谢所有与会者的参与，下次会议再见。</p>',13)])])}const _=i(o,[["render",r]]);export{p as __pageData,_ as default};
